    47→namespace Nethermind.Merge.Plugin;
    48→
    49→public partial class MergePlugin(ChainSpec chainSpec, IMergeConfig mergeConfig) : IConsensusWrapperPlugin
    50→{
    51→    protected INethermindApi _api = null!;
    52→    private ILogger _logger;
    53→    private ISyncConfig _syncConfig = null!;
    54→    protected IBlocksConfig _blocksConfig = null!;
    55→    protected ITxPoolConfig _txPoolConfig = null!;
    56→    protected IPoSSwitcher _poSSwitcher = NoPoS.Instance;
    57→    private IBlockCacheService _blockCacheService = null!;
    58→    private InvalidChainTracker.InvalidChainTracker _invalidChainTracker = null!;
    59→
    60→    private IMergeBlockProductionPolicy? _mergeBlockProductionPolicy;
    61→
    62→    public virtual string Name => "Merge";
    63→    public virtual string Description => "Merge plugin for ETH1-ETH2";
    64→    public string Author => "Nethermind";
    65→
    66→    protected virtual bool MergeEnabled => mergeConfig.Enabled &&
    67→                                           chainSpec.SealEngineType is SealEngineType.BeaconChain or SealEngineType.Clique or SealEngineType.Ethash;
    68→    public int Priority => PluginPriorities.Merge;
    69→
    70→    public virtual Task Init(INethermindApi nethermindApi)
    71→    {
    72→        _api = nethermindApi;
    73→        _syncConfig = nethermindApi.Config<ISyncConfig>();
    74→        _blocksConfig = nethermindApi.Config<IBlocksConfig>();
    75→        _txPoolConfig = nethermindApi.Config<ITxPoolConfig>();
    76→
    77→        MigrateSecondsPerSlot(_blocksConfig, mergeConfig);
    78→
    79→        _logger = _api.LogManager.GetClassLogger();
    80→
    81→        EnsureNotConflictingSettings();
    82→
    83→        if (MergeEnabled)
    84→        {
    85→            if (_api.DbProvider is null) throw new ArgumentException(nameof(_api.DbProvider));
    86→            if (_api.SpecProvider is null) throw new ArgumentException(nameof(_api.SpecProvider));
    87→
    88→            EnsureJsonRpcUrl();
    89→            EnsureReceiptAvailable();
    90→
    91→            _blockCacheService = _api.Context.Resolve<IBlockCacheService>();
    92→            _poSSwitcher = _api.Context.Resolve<IPoSSwitcher>();
    93→            _invalidChainTracker = _api.Context.Resolve<InvalidChainTracker.InvalidChainTracker>();
    94→            if (_txPoolConfig.BlobsSupport.SupportsReorgs())
    95→            {
    96→                ProcessedTransactionsDbCleaner processedTransactionsDbCleaner = new(_api.Context.Resolve<IManualBlockFinalizationManager>(), _api.DbProvider.BlobTransactionsDb.GetColumnDb(BlobTxsColumns.ProcessedTxs), _api.LogManager);
    97→                _api.DisposeStack.Push(processedTransactionsDbCleaner);
    98→            }
    99→
   100→            _api.GossipPolicy = new MergeGossipPolicy(_api.GossipPolicy, _poSSwitcher, _blockCacheService);
   101→
   102→            _api.BlockPreprocessor.AddFirst(new MergeProcessingRecoveryStep(_poSSwitcher));
   103→        }
   104→
   105→        return Task.CompletedTask;
   106→    }
   107→
   108→    private void EnsureNotConflictingSettings()
   109→    {
   110→        if (!mergeConfig.Enabled && mergeConfig.TerminalTotalDifficulty is not null)
   111→        {
   112→            throw new InvalidConfigurationException(
   113→                $"{nameof(MergeConfig)}.{nameof(MergeConfig.TerminalTotalDifficulty)} cannot be set when {nameof(MergeConfig)}.{nameof(MergeConfig.Enabled)} is false.",
   114→                ExitCodes.ConflictingConfigurations);
   115→        }
   116→    }
   117→
   118→    internal static void MigrateSecondsPerSlot(IBlocksConfig blocksConfig, IMergeConfig mergeConfig)
   119→    {
   120→        ulong defaultValue = blocksConfig.GetDefaultValue<ulong>(nameof(IBlocksConfig.SecondsPerSlot));
   121→        if (blocksConfig.SecondsPerSlot != mergeConfig.SecondsPerSlot)
   122→        {
   123→            if (blocksConfig.SecondsPerSlot == defaultValue)
   124→            {
   125→                blocksConfig.SecondsPerSlot = mergeConfig.SecondsPerSlot;
   126→            }
   127→            else if (mergeConfig.SecondsPerSlot == defaultValue)
   128→            {
   129→                mergeConfig.SecondsPerSlot = blocksConfig.SecondsPerSlot;
   130→            }
   131→            else
   132→            {
