   120→                    }
   121→                    s.AddSingleton<ApplicationLifetime>();
   122→                    startup.ConfigureServices(s);
   123→                })
   124→                .UseUrls(urls)
   125→                .ConfigureLogging(logging =>
   126→                {
   127→                    logging.SetMinimumLevel(LogLevel.Information);
   128→                    logging.ClearProviders();
   129→                    logging.AddProvider(new CustomMicrosoftLoggerProvider(_logManager));
   130→                    logging.Configure(options =>
