    95→    public void Configure(IApplicationBuilder app, IWebHostEnvironment env, IJsonRpcProcessor jsonRpcProcessor, IJsonRpcService jsonRpcService, IJsonRpcLocalStats jsonRpcLocalStats, IJsonSerializer jsonSerializer, ApplicationLifetime lifetime)
    96→    {
    97→        if (env.IsDevelopment())
    98→        {
    99→            app.UseDeveloperExceptionPage();
   100→        }
   101→
   102→        app.UseRouting();
   103→        app.UseCors();
   104→
   105→        IConfigProvider? configProvider = app.ApplicationServices.GetService<IConfigProvider>();
   106→        IRpcAuthentication? rpcAuthentication = app.ApplicationServices.GetService<IRpcAuthentication>();
   107→
   108→        if (configProvider is null)
   109→        {
