   111→        }
   112→
   113→        ILogManager? logManager = app.ApplicationServices.GetService<ILogManager>() ?? NullLogManager.Instance;
   114→        ILogger logger = logManager.GetClassLogger();
   115→        IInitConfig initConfig = configProvider.GetConfig<IInitConfig>();
   116→        IJsonRpcConfig jsonRpcConfig = configProvider.GetConfig<IJsonRpcConfig>();
   117→        IJsonRpcUrlCollection jsonRpcUrlCollection = app.ApplicationServices.GetRequiredService<IJsonRpcUrlCollection>();
   118→        IHealthChecksConfig healthChecksConfig = configProvider.GetConfig<IHealthChecksConfig>();
   119→
   120→        // If request is local, don't use response compression,
   121→        // as it allocates a lot, but doesn't improve much for loopback
   122→        app.UseWhen(ctx =>
   123→            !IsLocalhost(ctx.Connection.RemoteIpAddress),
   124→            builder => builder.UseResponseCompression());
   125→
   126→        if (initConfig.WebSocketsEnabled)
   127→        {
