   176→                return;
   177→            }
   178→
   179→            if (!jsonRpcUrlCollection.TryGetValue(ctx.Connection.LocalPort, out JsonRpcUrl jsonRpcUrl) || !jsonRpcUrl.RpcEndpoint.HasFlag(RpcEndpoint.Http))
   180→            {
   181→                ctx.Response.StatusCode = (int)HttpStatusCode.NotFound;
