   190→                    return;
   191→                }
   192→            }
   193→
   194→            if (method == "GET" && ctx.Request.Headers.Accept.Count > 0 &&
   195→                !ctx.Request.Headers.Accept[0].Contains("text/html", StringComparison.Ordinal))
   196→            {
   197→                await ctx.Response.WriteAsync("Nethermind JSON RPC");
   198→            }
