   211→                {
   212→                    using JsonRpcContext jsonRpcContext = JsonRpcContext.Http(jsonRpcUrl);
   213→                    await foreach (JsonRpcResult result in jsonRpcProcessor.ProcessAsync(request, jsonRpcContext))
