   216→                        {
   217→                            await using Stream stream = jsonRpcConfig.BufferResponses ? RecyclableStream.GetStream("http") : null;
   218→                            CountingWriter resultWriter = stream is not null ? new CountingStreamPipeWriter(stream) : new CountingPipeWriter(ctx.Response.BodyWriter);
   219→                            try
   220→                            {
   221→                                ctx.Response.ContentType = "application/json";
   222→                                ctx.Response.StatusCode = GetStatusCode(result);
   223→
   224→                                if (result.IsCollection)
   225→                                {
   226→                                    resultWriter.Write(_jsonOpeningBracket);
   227→                                    bool first = true;
   228→                                    JsonRpcBatchResultAsyncEnumerator enumerator = result.BatchedResponses.GetAsyncEnumerator(CancellationToken.None);
   229→                                    try
   230→                                    {
   231→                                        while (await enumerator.MoveNextAsync())
   232→                                        {
   233→                                            JsonRpcResult.Entry entry = enumerator.Current;
   234→                                            using (entry)
   235→                                            {
   236→                                                if (!first)
   237→                                                {
   238→                                                    resultWriter.Write(_jsonComma);
   239→                                                }
   240→
   241→                                                first = false;
   242→                                                await jsonSerializer.SerializeAsync(resultWriter, entry.Response);
   243→                                                _ = jsonRpcLocalStats.ReportCall(entry.Report);
   244→
   245→                                                // We reached the limit and don't want to responded to more request in the batch
   246→                                                if (!jsonRpcContext.IsAuthenticated && resultWriter.WrittenCount > jsonRpcConfig.MaxBatchResponseBodySize)
   247→                                                {
