    13→public class JsonRpcUrlCollection : Dictionary<int, JsonRpcUrl>, IJsonRpcUrlCollection
    14→{
    15→    private readonly ILogger _logger;
    16→    private readonly IJsonRpcConfig _jsonRpcConfig;
    17→
    18→    public JsonRpcUrlCollection(ILogManager logManager, IJsonRpcConfig jsonRpcConfig, bool includeWebSockets)
    19→    {
    20→        _logger = logManager?.GetClassLogger() ?? throw new ArgumentNullException(nameof(logManager));
    21→        _jsonRpcConfig = jsonRpcConfig ?? throw new ArgumentNullException(nameof(jsonRpcConfig));
    22→
    23→        if (_jsonRpcConfig.Enabled)
    24→        {
    25→            BuildUrls(includeWebSockets);
    26→        }
    27→    }
    28→
    29→    public string[] Urls => Values.Select(static x => x.ToString()).ToArray();
    30→
    31→    private void BuildUrls(bool includeWebSockets)
    32→    {
    33→        bool hasEngineApi = _jsonRpcConfig.EnabledModules.Any(static m => m.Equals(ModuleType.Engine, StringComparison.OrdinalIgnoreCase));
    34→        long? maxRequestBodySize = hasEngineApi ? SocketClient<WebSocketMessageStream>.MAX_REQUEST_BODY_SIZE_FOR_ENGINE_API : _jsonRpcConfig.MaxRequestBodySize;
    35→        JsonRpcUrl defaultUrl = new(Uri.UriSchemeHttp, _jsonRpcConfig.Host, _jsonRpcConfig.Port, RpcEndpoint.Http, hasEngineApi, _jsonRpcConfig.EnabledModules, maxRequestBodySize);
    36→
    37→        Add(defaultUrl.Port, defaultUrl);
    38→
    39→        if (includeWebSockets)
    40→        {
    41→            if (_jsonRpcConfig.WebSocketsPort != _jsonRpcConfig.Port)
    42→            {
    43→                JsonRpcUrl defaultWebSocketUrl = (JsonRpcUrl)defaultUrl.Clone();
    44→                defaultWebSocketUrl.Port = _jsonRpcConfig.WebSocketsPort;
    45→                defaultWebSocketUrl.RpcEndpoint = RpcEndpoint.Ws;
    46→                Add(defaultWebSocketUrl.Port, defaultWebSocketUrl);
    47→            }
    48→            else
    49→            {
    50→                defaultUrl.RpcEndpoint |= RpcEndpoint.Ws;
    51→            }
    52→        }
    53→
    54→        BuildEngineUrls(includeWebSockets);
    55→
    56→        BuildAdditionalUrls(includeWebSockets);
    57→    }
    58→
    59→    private void BuildEngineUrls(bool includeWebSockets)
    60→    {
    61→        if (_jsonRpcConfig.EnginePort is null)
    62→        {
    63→            return;
    64→        }
    65→
    66→        if (string.IsNullOrWhiteSpace(_jsonRpcConfig.EngineHost)) // by default EngineHost is not null
    67→        {
    68→            if (_logger.IsWarn) _logger.Warn("Json RPC EngineHost is set to null, " +
    69→                "please set it to 127.0.0.1 if your CL Client is on the same machine " +
    70→                "or to 0.0.0.0 if your CL Client is on a separate machine");
    71→            return;
    72→        }
    73→        JsonRpcUrl url = new(Uri.UriSchemeHttp, _jsonRpcConfig.EngineHost, _jsonRpcConfig.EnginePort.Value,
    74→            RpcEndpoint.Http, true, _jsonRpcConfig.EngineEnabledModules.Append(ModuleType.Engine).ToArray(),
    75→            SocketClient<WebSocketMessageStream>.MAX_REQUEST_BODY_SIZE_FOR_ENGINE_API);
    76→
    77→        if (ContainsKey(url.Port))
    78→        {
    79→            if (_logger.IsWarn) _logger.Warn($"Execution Engine wants port {url.Port}, but port already in use; skipping...");
    80→            return;
    81→        }
    82→
    83→        if (includeWebSockets)
    84→        {
    85→            url.RpcEndpoint |= RpcEndpoint.Ws;
    86→        }
    87→
    88→        Add(url.Port, url);
    89→    }
    90→
    91→    private void BuildAdditionalUrls(bool includeWebSockets)
    92→    {
    93→        foreach (string additionalRpcUrl in _jsonRpcConfig.AdditionalRpcUrls)
    94→        {
    95→            try
    96→            {
    97→                JsonRpcUrl url = JsonRpcUrl.Parse(additionalRpcUrl);
    98→                if (!includeWebSockets && url.RpcEndpoint.HasFlag(RpcEndpoint.Ws))
    99→                {
   100→                    url.RpcEndpoint &= ~RpcEndpoint.Ws;
   101→                    if (url.RpcEndpoint == RpcEndpoint.None)
   102→                    {
   103→                        if (_logger.IsInfo) _logger.Info($"Additional JSON RPC URL '{url}' has web socket endpoint type and web sockets are not enabled; skipping...");
   104→                        continue;
   105→                    }
   106→                }
   107→
   108→                if (url.IsModuleEnabled(ModuleType.Engine) && _jsonRpcConfig.EnginePort is not null &&
   109→                    !string.IsNullOrWhiteSpace(_jsonRpcConfig.EngineHost))
   110→                {
   111→                    if (_logger.IsInfo) _logger.Info($"EngineUrl specified. EnginePort {_jsonRpcConfig.EnginePort} EngineHost {_jsonRpcConfig.EngineHost}. Additional JSON RPC URL '{url}' has engine module enabled. skipping...");
   112→                    continue;
   113→                }
   114→
   115→                if (ContainsKey(url.Port))
   116→                {
   117→                    if (_logger.IsInfo) _logger.Info($"Additional JSON RPC URL '{url}' wants port {url.Port}, but port already in use; skipping...");
   118→                }
   119→                else
   120→                {
   121→                    Add(url.Port, url);
   122→                }
   123→            }
   124→            catch (FormatException fe)
   125→            {
   126→                if (_logger.IsInfo) _logger.Info($"Additional JSON RPC URL packed value '{additionalRpcUrl}' format error: {fe.Message}; skipping...");
   127→            }
   128→        }
   129→    }
